package dev.amenhancer.module.hook

import android.content.Context
import android.content.res.AssetManager
import dev.amenhancer.module.lyrics.online.KanaDictionary

/**
 * Loads the shipped kana dictionary from the module's assets.
 *
 * The asset is generated by scripts/build_kana_dictionary.py from IPADIC 2.7.0 and lives next to
 * its licence (assets/licenses/IPADIC-COPYING.txt). Loading is fail-open on purpose: a missing or
 * malformed asset leaves the dictionary absent, and the caller keeps the rule-only grouping instead
 * of failing the lyric page. The parse is a one-off 358 KB read plus bounds-checked table copy, so
 * it happens lazily on the first caller rather than during module install.
 */
internal object KanaDictionaryAssets {

    /** The shipped asset name; keep in sync with scripts/build_kana_dictionary.py. */
    const val ASSET_NAME = "kana_dict.bin"

    /** The licence packaged next to the asset. */
    const val LICENSE_ASSET = "licenses/IPADIC-COPYING.txt"

    @Volatile
    private var cached: KanaDictionary? = null

    /** Why the last load failed, for the diagnostic log; null while the dictionary is available. */
    @Volatile
    var lastError: String? = null
        private set

    /** The dictionary for [context]'s assets, or null when the asset is unavailable. */
    fun load(context: Context): KanaDictionary? = load(context.assets)

    /** The dictionary for [assets], or null when the asset is unavailable. */
    fun load(assets: AssetManager): KanaDictionary? {
        cached?.let { return it }
        synchronized(this) {
            cached?.let { return it }
            return runCatching {
                assets.open(ASSET_NAME).use { stream -> KanaDictionary.fromBytes(stream.readBytes()) }
            }.onFailure { error ->
                lastError = error.message ?: error.javaClass.simpleName
                ModernXposedRuntime.log("kana dictionary unavailable: " + lastError, error)
            }.getOrNull()?.also { cached = it }
        }
    }

    /** Drops the cached dictionary; test-only seam. */
    fun resetForTest() {
        cached = null
        lastError = null
    }
}
